from collections import deque

def bfs_distances(graph, start):
    dist = {start: 0}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for nxt in graph[node]:
            if nxt not in dist:            # dist doubles as the visited set
                dist[nxt] = dist[node] + 1
                queue.append(nxt)
    return dist

