def count_components(n, edges):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n

    def dfs(node):
        visited[node] = True          # mark first, then explore
        for nxt in graph[node]:
            if not visited[nxt]:
                dfs(nxt)

    count = 0
    for node in range(n):             # every vertex, including isolated ones
        if not visited[node]:
            count += 1                # found a new component
            dfs(node)
    return count

def dfs_iterative(graph, start):
    visited = {start}
    stack = [start]
    while stack:
        node = stack.pop()
        for nxt in graph[node]:
            if nxt not in visited:
                visited.add(nxt)
                stack.append(nxt)
    return visited

print(count_components(5, [[0, 1], [1, 2], [3, 4]]))   # 2
print(count_components(4, []))                         # 4

