def build(n, edges):
    graph = {}
    for u, v in edges:
        graph.setdefault(u, []).append(v)
        graph.setdefault(v, []).append(u)
    return graph

def count_components(n, edges):
    graph = build(n, edges)
    seen, count = set(), 0
    for node in graph:
        if node not in seen:
            count += 1
            stack = [node]
            seen.add(node)
            while stack:
                cur = stack.pop()
                for nxt in graph[cur]:
                    if nxt not in seen:
                        seen.add(nxt)
                        stack.append(nxt)
    return count

