def has_cycle(n, edges):
    graph = [[] for _ in range(n)]
    for a, b in edges:
        graph[a].append(b)
    visited = set()

    def dfs(node):
        if node in visited:
            return True          # seen before: a cycle?
        visited.add(node)
        return any(dfs(nxt) for nxt in graph[node])

    return any(dfs(v) for v in range(n))
